CREATE TABLE owners ("tenantId" varchar NOT NULL,id varchar NOT NULL,name varchar NOT NULL,PRIMARY KEY("tenantId",id));
CREATE TABLE notes (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"tenantId" varchar NOT NULL,"ownerId" varchar NOT NULL,title varchar NOT NULL,body varchar DEFAULT NULL,amount numeric(20,2) NOT NULL DEFAULT '0.00',"createdAt" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,version integer NOT NULL DEFAULT 1,UNIQUE("tenantId",title),FOREIGN KEY("tenantId","ownerId") REFERENCES owners("tenantId",id));
CREATE TABLE audits (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"noteId" integer NOT NULL REFERENCES notes(id),action varchar NOT NULL CHECK(action IN ('create','update')));
INSERT INTO owners VALUES ('tenant-a','alice','Alice'),('tenant-a','bob','Bob A'),('tenant-b','bob','Bob B');
CREATE TABLE jobs (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"tenantId" varchar NOT NULL,"ownerId" varchar NOT NULL,key varchar NOT NULL,fingerprint varchar NOT NULL,title varchar NOT NULL,status varchar NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','done','failed')),attempts integer NOT NULL DEFAULT 0,"leaseToken" uuid,"leaseUntil" timestamptz,"resultId" integer REFERENCES notes(id),UNIQUE("tenantId","ownerId",key));
